rules.pseudocode:
// persistent: alwaysIn (int, 0 = undefined, +1 long, -1 short)
strongBull(i) = close[i] > open[i] && (close[i]-open[i]) >= bodyFraction*(high[i]-low[i]) && (high[i]-close[i]) <= tailFraction*(high[i]-low[i]) && (open[i]-low[i]) <= tailFraction*(high[i]-low[i]);
strongBear(i) = mirror;
flipLong  = (forall i in 0..consecutiveBars-1: strongBull(i)) && (high[0] - high[1]) >= extensionTicks*tickSize;
flipShort = (forall i in 0..consecutiveBars-1: strongBear(i)) && (low[1] - low[0])  >= extensionTicks*tickSize;
if (flipLong) alwaysIn = +1; else if (flipShort) alwaysIn = -1; // else unchanged
// long side of the rule:
alwaysIn == +1

// persistent: monthStartEquity, priorMonthResult
if (month(date[0]) != month(date[1])) { priorMonthResult = NetProfit - monthStartEquity; monthStartEquity = NetProfit }
priorMonthResult >= 0

// persistent, reset on Date change
if (date[0] != date[1]) countertrendEntriesToday = 0;
if (newEntryFilled && entryDirection != alwaysIn) countertrendEntriesToday++;
countertrendEntriesToday < maxCountertrend

// persistent, latched on the date change
if (date[0] != date[1]) priorSessionAlwaysIn = alwaysIn[1];
priorSessionAlwaysIn == +1
